 const [tools,setTools]=useState<Tool[]>([]),[skills,setSkills]=useState<Skill[]>([]),[knowledge,setKnowledge]=useState<Resource[]>([]),[memories,setMemories]=useState<Resource[]>([]),[agentApps,setAgentApps]=useState<Application[]>([]),[models,setModels]=useState<ModelConnection[]>([]),[search,setSearch]=useState('');
