 const [toolDrawer,setToolDrawer]=useState(false),[skillDrawer,setSkillDrawer]=useState(false),[observeOpen,setObserveOpen]=useState(false),[versionOpen,setVersionOpen]=useState(false),[checkOpen,setCheckOpen]=useState(false);
