 const openObserve=async()=>{setObserveOpen(true);setDrawerBusy(true);setRunDetail(null);try{setRuns(await api.get<Run[]>(`/api/apps/${appId}/runs`))}catch(e){notify((e as Error).message,true)}finally{setDrawerBusy(false)}};
 const selectRun=async(run:Run)=>{setDrawerBusy(true);try{setRunDetail(await api.get<Run>(`/api/runs/${run.id}`))}catch(e){notify((e as Error).message,true)}finally{setDrawerBusy(false)}};
 const openVersions=async()=>{if(!workflow)return;setVersionOpen(true);setDrawerBusy(true);try{setVersions(await api.get<Workflow[]>(`/api/workflows/${workflow.id}/versions`))}catch(e){notify((e as Error).message,true)}finally{setDrawerBusy(false)}};
 const rollback=async(version:number)=>{if(!workflow||!(await appConfirm(`${dirty?'当前未保存修改将被丢弃。\n':''}确认切换到已发布版本 v${version}？`)))return;setDrawerBusy(true);try{const updated=await api.post<Workflow>(`/api/workflows/${workflow.id}/rollback/${version}`);const converted=fromWorkflow(updated);setWorkflow(updated);setNodes(converted.nodes);setEdges(converted.edges);setSaved(converted.repaired?'__missing-boundary-nodes__':serializeEditor(converted.nodes,converted.edges,app));history.current=[];future.current=[];setSelected('');setSelectedEdge('');setVersions(await api.get<Workflow[]>(`/api/workflows/${workflow.id}/versions`));notify(converted.repaired?`已切换到 v${version}，并补齐缺失的结构节点`:`当前版本已切换为 v${version}`)}catch(e){notify((e as Error).message,true)}finally{setDrawerBusy(false)}};
 const approve=async(sequence:number,approved:boolean)=>{if(!testRun)return;try{await api.post(`/api/runs/${testRun.id}/approvals/${sequence}/${approved?'approve':'reject'}`,{reason:approved?'用户批准':'用户拒绝'});setTestRun(await api.get<Run>(`/api/runs/${testRun.id}`));notify(approved?'已批准工具调用':'已拒绝工具调用')}catch(e){notify((e as Error).message,true)}};
 const leave=async ()=>{if(dirty&&!(await appConfirm('工作流尚未保存，确定离开吗？')))return;back()};
